Below is a reusable Pulumi `ComponentResource` for the requested S3 bucket, PostgreSQL RDS instance, and IAM identity for Kubernetes service accounts. It expects networking and the EKS OIDC provider to be supplied by the surrounding stack.

### `package.json`

```json
{
  "name": "application-infrastructure",
  "private": true,
  "main": "index.ts",
  "scripts": {
    "build": "tsc",
    "preview": "pulumi preview",
    "up": "pulumi up"
  },
  "dependencies": {
    "@pulumi/aws": "^6.0.0",
    "@pulumi/pulumi": "^3.0.0"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "typescript": "^5.0.0"
  }
}
```

### `tsconfig.json`

```json
{
  "compilerOptions": {
    "strict": true,
    "target": "ES2022",
    "module": "commonjs",
    "moduleResolution": "node",
    "esModuleInterop": true,
    "outDir": "bin"
  },
  "include": ["*.ts"]
}
```

## Component

### `applicationService.ts`

```typescript
import * as aws from "@pulumi/aws";
import * as pulumi from "@pulumi/pulumi";

export type Environment = "dev" | "prod";

export interface ApplicationServiceArgs {
    environment: Environment;

    vpcId: pulumi.Input<string>;
    privateSubnetIds: pulumi.Input<pulumi.Input<string>[]>;

    /**
     * Security groups allowed to connect to PostgreSQL.
     * Usually this is the EKS managed node group or pod security group.
     */
    databaseClientSecurityGroupIds: pulumi.Input<pulumi.Input<string>[]>;

    databaseName: pulumi.Input<string>;
    databaseUsername: pulumi.Input<string>;
    databasePassword: pulumi.Input<string>;

    /**
     * EKS IAM OIDC provider details for IRSA.
     */
    oidcProviderArn: pulumi.Input<string>;
    oidcProviderUrl: pulumi.Input<string>;

    kubernetesNamespace?: pulumi.Input<string>;
    kubernetesServiceAccount?: pulumi.Input<string>;

    /**
     * Required in prod because the assets bucket is replicated to us-west-2.
     */
    replicationProvider?: aws.Provider;
}

export class ApplicationService extends pulumi.ComponentResource {
    public readonly bucket: aws.s3.BucketV2;
    public readonly bucketArn: pulumi.Output<string>;

    public readonly database: aws.rds.Instance;
    public readonly databaseSecurityGroup: aws.ec2.SecurityGroup;
    public readonly databaseConnectionString: pulumi.Output<string>;

    public readonly serviceAccountRole: aws.iam.Role;
    public readonly serviceAccountRoleArn: pulumi.Output<string>;

    /**
     * Dev-only programmatic IAM user. Prod uses IRSA exclusively.
     */
    public readonly developmentUser?: aws.iam.User;
    public readonly developmentAccessKey?: aws.iam.AccessKey;
    public readonly developmentAccessKeyId?: pulumi.Output<string>;
    public readonly developmentSecretAccessKey?: pulumi.Output<string>;

    public readonly replicationBucket?: aws.s3.BucketV2;

    constructor(
        name: string,
        args: ApplicationServiceArgs,
        opts?: pulumi.ComponentResourceOptions,
    ) {
        super("example:platform:ApplicationService", name, {}, opts);

        const childOpts: pulumi.CustomResourceOptions = { parent: this };
        const namespace = args.kubernetesNamespace ?? "default";
        const serviceAccount = args.kubernetesServiceAccount ?? name;

        /*
         * Application assets bucket
         */
        this.bucket = new aws.s3.BucketV2(`${name}-assets`, {
            forceDestroy: args.environment === "dev",
            tags: {
                Name: `${name}-assets`,
                Environment: args.environment,
                ManagedBy: "Pulumi",
            },
        }, childOpts);

        new aws.s3.BucketVersioningV2(`${name}-assets-versioning`, {
            bucket: this.bucket.id,
            versioningConfiguration: {
                status: "Enabled",
            },
        }, childOpts);

        new aws.s3.BucketServerSideEncryptionConfigurationV2(
            `${name}-assets-encryption`,
            {
                bucket: this.bucket.id,
                rules: [{
                    applyServerSideEncryptionByDefault: {
                        sseAlgorithm: "AES256",
                    },
                    bucketKeyEnabled: true,
                }],
            },
            childOpts,
        );

        new aws.s3.BucketPublicAccessBlock(`${name}-assets-public-access`, {
            bucket: this.bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, childOpts);

        new aws.s3.BucketOwnershipControls(`${name}-assets-ownership`, {
            bucket: this.bucket.id,
            rule: {
                objectOwnership: "BucketOwnerEnforced",
            },
        }, childOpts);

        /*
         * Reject unencrypted transport. This does not make the bucket public.
         */
        new aws.s3.BucketPolicy(`${name}-assets-policy`, {
            bucket: this.bucket.id,
            policy: pulumi.all([this.bucket.arn]).apply(([bucketArn]) =>
                aws.iam.getPolicyDocumentOutput({
                    statements: [{
                        sid: "DenyInsecureTransport",
                        effect: "Deny",
                        principals: [{
                            type: "*",
                            identifiers: ["*"],
                        }],
                        actions: ["s3:GetObject"],
                        resources: [`${bucketArn}/*`],
                        conditions: [{
                            test: "Bool",
                            variable: "aws:SecureTransport",
                            values: ["false"],
                        }],
                    }],
                }).json
            ),
        }, childOpts);

        /*
         * RDS PostgreSQL
         */
        this.databaseSecurityGroup = new aws.ec2.SecurityGroup(
            `${name}-database`,
            {
                vpcId: args.vpcId,
                description: `PostgreSQL access for ${name}`,
                revokeRulesOnDelete: true,
                ingress: [{
                    protocol: "tcp",
                    fromPort: 5432,
                    toPort: 5432,
                    securityGroups: args.databaseClientSecurityGroupIds,
                    description: "PostgreSQL from application workloads",
                }],
                egress: [],
                tags: {
                    Name: `${name}-database`,
                    Environment: args.environment,
                },
            },
            childOpts,
        );

        const subnetGroup = new aws.rds.SubnetGroup(`${name}-database`, {
            subnetIds: args.privateSubnetIds,
            tags: {
                Name: `${name}-database`,
                Environment: args.environment,
            },
        }, childOpts);

        const databaseParameterGroup = new aws.rds.ParameterGroup(
            `${name}-postgresql`,
            {
                family: "postgres16",
                parameters: [{
                    name: "rds.force_ssl",
                    value: "1",
                }],
                tags: {
                    Environment: args.environment,
                },
            },
            childOpts,
        );

        this.database = new aws.rds.Instance(`${name}-postgresql`, {
            engine: "postgres",
            engineVersion: "16",
            instanceClass:
                args.environment === "prod"
                    ? "db.t3.medium"
                    : "db.t3.micro",

            allocatedStorage: args.environment === "prod" ? 100 : 20,
            maxAllocatedStorage: args.environment === "prod" ? 500 : 100,
            storageType: "gp3",
            storageEncrypted: args.environment === "prod",

            dbName: args.databaseName,
            username: args.databaseUsername,
            password: args.databasePassword,

            dbSubnetGroupName: subnetGroup.name,
            parameterGroupName: databaseParameterGroup.name,
            vpcSecurityGroupIds: [this.databaseSecurityGroup.id],

            publiclyAccessible: false,
            multiAz: args.environment === "prod",

            backupRetentionPeriod: args.environment === "prod" ? 30 : 7,
            backupWindow: "03:00-04:00",
            maintenanceWindow: "sun:04:00-sun:05:00",
            copyTagsToSnapshot: true,

            deletionProtection: true,
            skipFinalSnapshot: false,
            finalSnapshotIdentifier: `${name}-${args.environment}-final`,
            applyImmediately: args.environment === "dev",

            autoMinorVersionUpgrade: true,
            enabledCloudwatchLogsExports: ["postgresql", "upgrade"],

            tags: {
                Name: `${name}-postgresql`,
                Environment: args.environment,
                ManagedBy: "Pulumi",
            },
        }, {
            ...childOpts,
            protect: args.environment === "prod",
        });

        this.databaseConnectionString = pulumi.secret(
            pulumi
                .all([
                    args.databaseUsername,
                    args.databasePassword,
                    this.database.address,
                    this.database.port,
                    args.databaseName,
                ])
                .apply(([username, password, host, port, database]) => {
                    const encodedUser = encodeURIComponent(username);
                    const encodedPassword = encodeURIComponent(password);

                    return `postgresql://${encodedUser}:${encodedPassword}` +
                        `@${host}:${port}/${database}?sslmode=require`;
                }),
        );

        /*
         * IAM role for Kubernetes service accounts (IRSA)
         */
        const oidcIssuer = pulumi.output(args.oidcProviderUrl).apply(
            url => url.replace(/^https:\/\//, "").replace(/\/$/, ""),
        );

        const assumeRolePolicy = pulumi
            .all([
                args.oidcProviderArn,
                oidcIssuer,
                namespace,
                serviceAccount,
            ])
            .apply(([providerArn, issuer, ns, sa]) =>
                aws.iam.getPolicyDocumentOutput({
                    statements: [{
                        effect: "Allow",
                        actions: ["sts:AssumeRoleWithWebIdentity"],
                        principals: [{
                            type: "Federated",
                            identifiers: [providerArn],
                        }],
                        conditions: [
                            {
                                test: "StringEquals",
                                variable: `${issuer}:aud`,
                                values: ["sts.amazonaws.com"],
                            },
                            {
                                test: "StringEquals",
                                variable: `${issuer}:sub`,
                                values: [`system:serviceaccount:${ns}:${sa}`],
                            },
                        ],
                    }],
                }).json
            );

        this.serviceAccountRole = new aws.iam.Role(
            `${name}-service-account`,
            {
                assumeRolePolicy,
                description: `IRSA role for ${namespace}/${serviceAccount}`,
                tags: {
                    Environment: args.environment,
                    KubernetesNamespace: namespace,
                    KubernetesServiceAccount: serviceAccount,
                },
            },
            childOpts,
        );

        const applicationPolicy = new aws.iam.Policy(`${name}-application`, {
            description: `Least-privilege access to ${name} assets`,
            policy: this.bucket.arn.apply(bucketArn =>
                aws.iam.getPolicyDocumentOutput({
                    statements: [
                        {
                            sid: "ListAssetsBucket",
                            effect: "Allow",
                            actions: [
                                "s3:ListBucket",
                                "s3:GetBucketLocation",
                            ],
                            resources: [bucketArn],
                        },
                        {
                            sid: "ReadWriteAssets",
                            effect: "Allow",
                            actions: [
                                "s3:GetObject",
                                "s3:PutObject",
                                "s3:DeleteObject",
                            ],
                            resources: [`${bucketArn}/*`],
                        },
                    ],
                }).json
            ),
            tags: {
                Environment: args.environment,
            },
        }, childOpts);

        new aws.iam.RolePolicyAttachment(`${name}-application`, {
            role: this.serviceAccountRole.name,
            policyArn: applicationPolicy.arn,
        }, childOpts);

        /*
         * Dev additionally receives a programmatic IAM user. Its secret access
         * key remains a Pulumi secret and must not be committed to stack YAML.
         */
        if (args.environment === "dev") {
            this.developmentUser = new aws.iam.User(`${name}-developer`, {
                tags: {
                    Environment: args.environment,
                    Purpose: "Development programmatic access",
                },
            }, childOpts);

            new aws.iam.UserPolicyAttachment(`${name}-developer`, {
                user: this.developmentUser.name,
                policyArn: applicationPolicy.arn,
            }, childOpts);

            this.developmentAccessKey = new aws.iam.AccessKey(
                `${name}-developer`,
                {
                    user: this.developmentUser.name,
                },
                childOpts,
            );

            this.developmentAccessKeyId = this.developmentAccessKey.id;
            this.developmentSecretAccessKey = pulumi.secret(
                this.developmentAccessKey.secret,
            );
        }

        /*
         * Prod cross-region replication to us-west-2.
         */
        if (args.environment === "prod") {
            if (!args.replicationProvider) {
                throw new Error(
                    "replicationProvider is required in prod and must target us-west-2",
                );
            }

            this.replicationBucket = new aws.s3.BucketV2(
                `${name}-assets-replica`,
                {
                    tags: {
                        Name: `${name}-assets-replica`,
                        Environment: args.environment,
                        ManagedBy: "Pulumi",
                    },
                },
                {
                    parent: this,
                    provider: args.replicationProvider,
                    protect: true,
                },
            );

            const replicaVersioning = new aws.s3.BucketVersioningV2(
                `${name}-assets-replica-versioning`,
                {
                    bucket: this.replicationBucket.id,
                    versioningConfiguration: {
                        status: "Enabled",
                    },
                },
                {
                    parent: this,
                    provider: args.replicationProvider,
                },
            );

            new aws.s3.BucketServerSideEncryptionConfigurationV2(
                `${name}-assets-replica-encryption`,
                {
                    bucket: this.replicationBucket.id,
                    rules: [{
                        applyServerSideEncryptionByDefault: {
                            sseAlgorithm: "AES256",
                        },
                    }],
                },
                {
                    parent: this,
                    provider: args.replicationProvider,
                },
            );

            new aws.s3.BucketPublicAccessBlock(
                `${name}-assets-replica-public-access`,
                {
                    bucket: this.replicationBucket.id,
                    blockPublicAcls: true,
                    blockPublicPolicy: true,
                    ignorePublicAcls: true,
                    restrictPublicBuckets: true,
                },
                {
                    parent: this,
                    provider: args.replicationProvider,
                },
            );

            const replicationRole = new aws.iam.Role(
                `${name}-replication`,
                {
                    assumeRolePolicy: aws.iam.getPolicyDocumentOutput({
                        statements: [{
                            effect: "Allow",
                            actions: ["sts:AssumeRole"],
                            principals: [{
                                type: "Service",
                                identifiers: ["s3.amazonaws.com"],
                            }],
                        }],
                    }).json,
                },
                childOpts,
            );

            const replicationPolicy = new aws.iam.RolePolicy(
                `${name}-replication`,
                {
                    role: replicationRole.id,
                    policy: pulumi
                        .all([this.bucket.arn, this.replicationBucket.arn])
                        .apply(([sourceArn, destinationArn]) =>
                            aws.iam.getPolicyDocumentOutput({
                                statements: [
                                    {
                                        effect: "Allow",
                                        actions: [
                                            "s3:GetReplicationConfiguration",
                                            "s3:ListBucket",
                                        ],
                                        resources: [sourceArn],
                                    },
                                    {
                                        effect: "Allow",
                                        actions: [
                                            "s3:GetObjectVersionForReplication",
                                            "s3:GetObjectVersionAcl",
                                            "s3:GetObjectVersionTagging",
                                        ],
                                        resources: [`${sourceArn}/*`],
                                    },
                                    {
                                        effect: "Allow",
                                        actions: [
                                            "s3:ReplicateObject",
                                            "s3:ReplicateDelete",
                                            "s3:ReplicateTags",
                                        ],
                                        resources: [`${destinationArn}/*`],
                                    },
                                ],
                            }).json
                        ),
                },
                childOpts,
            );

            new aws.s3.BucketReplicationConfig(
                `${name}-assets-replication`,
                {
                    bucket: this.bucket.id,
                    role: replicationRole.arn,
                    rules: [{
                        id: "replicate-to-us-west-2",
                        status: "Enabled",
                        priority: 1,
                        filter: {
                            prefix: "",
                        },
                        destination: {
                            bucket: this.replicationBucket.arn,
                            storageClass: "STANDARD",
                        },
                        deleteMarkerReplication: {
                            status: "Enabled",
                        },
                    }],
                },
                {
                    parent: this,
                    dependsOn: [
                        replicaVersioning,
                        replicationPolicy,
                    ],
                },
            );
        }

        this.bucketArn = this.bucket.arn;
        this.serviceAccountRoleArn = this.serviceAccountRole.arn;

        this.registerOutputs({
            bucketName: this.bucket.bucket,
            bucketArn: this.bucket.arn,
            replicationBucketName: this.replicationBucket?.bucket,

            databaseAddress: this.database.address,
            databasePort: this.database.port,
            databaseConnectionString: this.databaseConnectionString,

            serviceAccountRoleArn: this.serviceAccountRole.arn,

            developmentAccessKeyId: this.developmentAccessKeyId,
            developmentSecretAccessKey: this.developmentSecretAccessKey,
        });
    }
}
