## Stack entry point

### `index.ts`

```typescript
import * as aws from "@pulumi/aws";
import * as pulumi from "@pulumi/pulumi";
import {
    ApplicationService,
    Environment,
} from "./applicationService";

const config = new pulumi.Config();
const awsConfig = new pulumi.Config("aws");

const environment = config.require("environment") as Environment;

if (environment !== "dev" && environment !== "prod") {
    throw new Error("environment must be either 'dev' or 'prod'");
}

const expectedRegion =
    environment === "prod" ? "us-east-1" : "us-east-2";

const configuredRegion = awsConfig.require("region");

if (configuredRegion !== expectedRegion) {
    throw new Error(
        `${environment} must use AWS region ${expectedRegion}; ` +
        `received ${configuredRegion}`,
    );
}

/*
 * These values should normally be exported by the stack's VPC/EKS component.
 * They are configuration inputs here so this component can be deployed
 * independently of a particular EKS implementation.
 */
const vpcId = config.require("vpcId");
const privateSubnetIds = config.requireObject<string[]>("privateSubnetIds");
const applicationSecurityGroupIds =
    config.requireObject<string[]>("applicationSecurityGroupIds");

const oidcProviderArn = config.require("oidcProviderArn");
const oidcProviderUrl = config.require("oidcProviderUrl");

/*
 * Pulumi encrypts this value in the stack state and stack configuration.
 * Set it with:
 *
 * pulumi config set --secret databasePassword '...'
 */
const databasePassword = config.requireSecret("databasePassword");

const replicaProvider = environment === "prod"
    ? new aws.Provider("us-west-2", {
        region: "us-west-2",
    })
    : undefined;

const application = new ApplicationService("webapp", {
    environment,

    vpcId,
    privateSubnetIds,
    databaseClientSecurityGroupIds: applicationSecurityGroupIds,

    databaseName: "webapp",
    databaseUsername: "webapp_admin",
    databasePassword,

    oidcProviderArn,
    oidcProviderUrl,
    kubernetesNamespace: "webapp",
    kubernetesServiceAccount: "webapp",

    replicationProvider: replicaProvider,
});

export const assetsBucketName = application.bucket.bucket;
export const assetsBucketArn = application.bucketArn;

export const databaseAddress = application.database.address;
export const databasePort = application.database.port;
export const databaseConnectionString =
    application.databaseConnectionString;

export const serviceAccountRoleArn =
    application.serviceAccountRoleArn;

export const replicaBucketName =
    application.replicationBucket?.bucket;

export const developmentAccessKeyId =
    application.developmentAccessKeyId;

export const developmentSecretAccessKey =
    application.developmentSecretAccessKey;
```

## Stack configurations

### `Pulumi.dev.yaml`

```yaml
config:
  aws:region: us-east-2

  application-infrastructure:environment: dev
  application-infrastructure:vpcId: vpc-REPLACE_ME

  application-infrastructure:privateSubnetIds:
    - subnet-REPLACE_ME_1
    - subnet-REPLACE_ME_2

  application-infrastructure:applicationSecurityGroupIds:
    - sg-REPLACE_ME

  application-infrastructure:oidcProviderArn: arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-2.amazonaws.com/id/REPLACE_ME
  application-infrastructure:oidcProviderUrl: https://oidc.eks.us-east-2.amazonaws.com/id/REPLACE_ME

  # Add with `pulumi config set --secret databasePassword ...`.
  # The ciphertext generated by Pulumi is safe to commit.
  application-infrastructure:databasePassword:
    secure: REPLACE_WITH_PULUMI_CIPHERTEXT
```

### `Pulumi.prod.yaml`

```yaml
config:
  aws:region: us-east-1

  application-infrastructure:environment: prod
  application-infrastructure:vpcId: vpc-REPLACE_ME

  application-infrastructure:privateSubnetIds:
    - subnet-REPLACE_ME_1
    - subnet-REPLACE_ME_2
    - subnet-REPLACE_ME_3

  application-infrastructure:applicationSecurityGroupIds:
    - sg-REPLACE_ME

  application-infrastructure:oidcProviderArn: arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/REPLACE_ME
  application-infrastructure:oidcProviderUrl: https://oidc.eks.us-east-1.amazonaws.com/id/REPLACE_ME

  application-infrastructure:databasePassword:
    secure: REPLACE_WITH_PULUMI_CIPHERTEXT
```

Create and configure stacks independently:

```bash
pulumi stack init dev
pulumi config set aws:region us-east-2
pulumi config set environment dev
pulumi config set --secret databasePassword 'replace-me'

pulumi stack init prod
pulumi config set aws:region us-east-1
pulumi config set environment prod
pulumi config set --secret databasePassword 'replace-me'
```

The Kubernetes service account must carry the resulting role annotation:

```yaml
apiVersion: v1
kind: ServiceAccount
metadata:
  name: webapp
  namespace: webapp
  annotations:
    eks.amazonaws.com/role-arn: <serviceAccountRoleArn>
```

This component provides:

- Versioned, AES-256 encrypted, non-public S3 storage.
- Cross-region S3 replication to `us-west-2` in prod.
- Private PostgreSQL with deletion protection and at least seven days of backups.
- Prod multi-AZ and encrypted RDS storage.
- OIDC-restricted IRSA role with bucket-scoped permissions.
- Dev-only programmatic IAM credentials, returned as Pulumi secrets.
- A Pulumi-secret database connection string.
- Independent dev/prod state through separate Pulumi stacks.
